/* Maddie Journey · local-first static prototype, no authentication or remote persistence. */
(function () {
  'use strict';
  const seed = window.MJ_SEED;
  if (!seed) { document.getElementById('app').textContent='Sample data could not be loaded.'; return; }
  const KEY='maddie-journey-demo-v3';
  const $=function(id){return document.getElementById(id);};
  const clone=function(x){return JSON.parse(JSON.stringify(x));};
  let data;
  try {const raw=JSON.parse(localStorage.getItem(KEY));data=(raw&&raw.version===seed.version&&Array.isArray(raw.employees)&&raw.employees.length===51)?raw:clone(seed);}catch(err){data=clone(seed);}
  data.viewers=clone(seed.viewers); data.divisions=clone(seed.divisions); data.stages=clone(seed.stages); data.kit=clone(seed.kit);
  let ui={tab:'overview',viewer:'giezelle',division:'all',activeDivision:'rmd',query:'',employee:data.employees[0].id,detail:'preview',drawer:false,roleModal:false,divisionModal:false,frequency:'monthly',mobile:false};
  try {const saved=JSON.parse(sessionStorage.getItem('maddie-journey-ui')||'null');if(saved&&saved.viewer)ui.viewer=saved.viewer;}catch(err){}
  const now=function(){return new Date().toISOString().slice(0,10);};
  const safe=function(v){return String(v===undefined||v===null?'':v).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];});};
  const money=function(n){return '₱'+(Number(n)||0).toLocaleString('en-PH',{maximumFractionDigits:2,minimumFractionDigits:2});};
  const viewer=function(){return data.viewers.find(function(v){return v.id===ui.viewer;})||data.viewers[0];};
  const emp=function(id){return data.employees.find(function(e){return e.id===(id||ui.employee);});};
  const div=function(id){return data.divisions.find(function(d){return d.id===id;})||{name:id,short:id,evaluators:[]};};
  const roleCanHead=function(e){const v=viewer();return !!(e&&(v.role==='head'||v.role==='corp')&&(v.divisions||[]).includes(e.division));};
  const isHR=function(){return viewer().role==='hr';};
  const canTrack=function(e){return isHR()||roleCanHead(e);};
  const canScore=function(e,k){return (k==='values'||k==='behavior')?isHR():roleCanHead(e);};
  const canReview=function(k){const r=viewer().role;return k==='corp'&&r==='corp';};
  const dateLabel=function(v){if(!v)return '—';const d=new Date(v+'T12:00:00');return isNaN(d.getTime())?safe(v):d.toLocaleDateString('en-PH',{month:'short',day:'numeric',year:'numeric'});};
  const escVal=function(v){return safe(v);};
  function persist(){try{localStorage.setItem(KEY,JSON.stringify(data));sessionStorage.setItem('maddie-journey-ui',JSON.stringify({viewer:ui.viewer}));}catch(err){toast('Browser storage unavailable. Export your work to avoid losing changes.');}}
  function audit(e,action){const entry={date:new Date().toISOString(),actor:viewer().name,action:action};e.modifiedAt=entry.date;e.audit.unshift(entry);e.audit=e.audit.slice(0,50);persist();}
  function toast(msg){let t=$('toast');if(!t){t=document.createElement('div');t.id='toast';t.className='toast';document.body.appendChild(t);}t.textContent=msg;setTimeout(function(){if(t.textContent===msg)t.remove();},3800);}
  function journeyPct(e){const bits=e.journey.flat();return Math.round(bits.filter(Boolean).length/Math.max(1,bits.length)*100);}
  function kitPct(e){return Math.round(e.kit.filter(Boolean).length/Math.max(1,e.kit.length)*100);}
  function score(e){return Math.round((e.scores.division*.15+e.scores.individual*.45+e.scores.values*.15+e.scores.behavior*.25)*100)/100;}
  function rating(v){return v>=95?'Excellent':v>=90?'Above Average':v>=80?'Average':v>=70?'Below Average':'Poor';}
  function attend(e){const a=e.attendance.filter(function(r){return r.verified;});const l=a.filter(function(r){return r.type==='Late';});const ab=a.filter(function(r){return r.type==='Absent';});const concerns=a.filter(function(r){return (r.type==='Late'&&r.approval!=='Excused')||(r.type==='Absent'&&r.approval==='Unapproved');});return {lates:l.length,absences:ab.length,concerns:concerns.length,lastLate:l.map(function(x){return x.date;}).sort().reverse()[0]||'',lastAbs:ab.map(function(x){return x.date;}).sort().reverse()[0]||'',records:a,clean:l.length===0&&ab.length===0};}
  const totalAvg=function(fn){return Math.round(data.employees.reduce(function(a,e){return a+fn(e);},0)/data.employees.length);};
  function approvedCount(){return data.employees.filter(function(e){return e.review.coo.status==='Approved';}).length;}
  function pendingCount(){return data.employees.filter(function(e){return e.review.coo.status!=='Approved';}).length;}
  const initials=function(str){return String(str).split(/\s+/).filter(Boolean).slice(0,2).map(function(x){return x[0];}).join('').toUpperCase();};
  const avatar=function(str){return '<span class="avatar" aria-hidden="true">'+safe(initials(str))+'</span>';};
  const pill=function(status){const t=String(status||'Pending');const cls=['Approved','Endorsed','Complete','Verified','Excellent'].includes(t)?'ok':['Returned','Rejected','Unapproved'].includes(t)?'bad':['Pending','Draft'].includes(t)?'warn':'info';return '<span class="tag '+cls+'">'+safe(t)+'</span>';};
  const button=function(label,action,attributes,cls){return '<button type="button" class="button '+(cls||'')+'" data-action="'+action+'" '+(attributes||'')+'>'+label+'</button>';};
  const input=function(key,value,opts){opts=opts||{};return '<input class="field" type="'+(opts.type||'text')+'" data-field="'+key+'" value="'+escVal(value)+'" '+(opts.min!==undefined?'min="'+opts.min+'" ':'')+(opts.max!==undefined?'max="'+opts.max+'" ':'')+(opts.step!==undefined?'step="'+opts.step+'" ':'')+(opts.disabled?'disabled ':'')+(opts.placeholder?'placeholder="'+safe(opts.placeholder)+'"':'')+'>';};
  const textArea=function(key,value,disabled,placeholder){return '<textarea class="field textarea" data-field="'+key+'" '+(disabled?'disabled ':'')+'placeholder="'+safe(placeholder||'Add a note…')+'">'+safe(value||'')+'</textarea>';};
  function opts(list,value){return list.map(function(x){return '<option value="'+safe(x.value)+'" '+(x.value===value?'selected':'')+'>'+safe(x.label)+'</option>';}).join('');}
  function select(key,value,items,disabled){return '<select class="field" data-field="'+key+'" '+(disabled?'disabled':'')+'>'+opts(items,value)+'</select>';}
  function linkedEmployee(e){return '<button class="link-btn" data-action="open" data-id="'+safe(e.id)+'">'+safe(e.name)+'</button>';}
  function progress(val){return '<div class="progress"><span style="width:'+Math.max(0,Math.min(100,val))+'%"></span></div>';}
  function topnav(){
    const v=viewer(),isObserver=['ceo','cso','coo'].includes(v.role);
    return '<div class="mobile-top"><div class="brand"><span class="logo">m.</span><b>Maddie Journey</b></div>'+button('☰','mobile','','small')+'</div>'+
    '<div class="topbar"><div class="breadcrumb">MADHOUSE / PEOPLE & CULTURE <strong>'+safe(title(ui.tab))+'</strong></div>'+
    '<div class="top-actions"><span class="tag warn demo-marker">DEMO DATA</span>'+
    '<button class="workspace-trigger" type="button" data-action="choose-workspace" aria-haspopup="dialog" aria-label="Switch workspace, currently '+safe(v.name)+'">'+
    avatar(v.name)+'<span class="workspace-trigger-copy"><b>'+safe(v.name)+'</b><small>'+(isObserver?'Observer · View only':isHR()?'HR · Editor':'Division · Editor')+'</small></span><span class="workspace-chevron" aria-hidden="true">⌄</span></button></div></div>';
  }
  const items=[['overview','◫','Overview'],['divisions','▦','Divisions'],['employees','◎','Employees'],['journey','◷','Journey stages'],['kit','▣','Welcome Maddie Kit'],['attendance','◩','Attendance'],['kpi','◈','KPI scorecards'],['approvals','✓','Approvals'],['audit','≡','Activity & data']];
  function sidebar(){
    const v=viewer(),own=assignedDivisionIds(),observer=['ceo','cso','coo'].includes(v.role);
    const visible=isHR()?['overview','divisions','employees','journey','kit','attendance','kpi','audit']
     :observer?['overview','divisions','employees','attendance','kpi','approvals']
     :['overview','divisions','employees','kpi','approvals'];
    const deptLinks=own.length?'<div class="sidebar-label division-side-label">My departments</div><nav class="nav division-shortcuts" aria-label="My departments">'+own.map(function(id){const d=div(id);return '<a href="#division/'+safe(id)+'" data-nav-division="'+safe(id)+'" class="'+(ui.tab==='division'&&ui.activeDivision===id?'active':'')+'"><span class="nav-icon">◈</span>'+safe(d.short)+'</a>';}).join('')+'</nav>':'';
    return '<aside class="sidebar"><div class="brand"><span class="logo">m.</span><span><b>Maddie Journey</b><small>People & Culture Workspace</small></span></div>'+
    '<div class="sidebar-label">My workspace</div><nav class="nav" aria-label="Main navigation">'+items.filter(function(i){return visible.includes(i[0]);}).map(function(i){return '<a href="#'+i[0]+'" data-nav="'+i[0]+'" class="'+(ui.tab===i[0]||(i[0]==='divisions'&&ui.tab==='division')?'active':'')+'"><span class="nav-icon">'+i[1]+'</span>'+safe(i[2])+'</a>';}).join('')+'</nav>'+
    deptLinks+'<div class="sidebar-bottom"><div class="demo">PROTOTYPE · Demo mode only<br>Edits stay on this device.</div><div class="sidebar-user">'+avatar(v.name)+'<span><b>'+safe(v.name)+'</b><small>'+safe(v.title)+'</small></span></div><button class="sidebar-switch" data-action="choose-workspace" type="button">Switch workspace ↗</button></div></aside>';
  }
  function title(t){if(t==='division')return div(ui.activeDivision).name+' · Evaluation';return {divisions:'Divisions',overview:'Overview',employees:'People directory',journey:'Employee journey',kit:'Welcome Maddie Kit',attendance:'Attendance analytics',kpi:'2026 KPI evaluations',approvals:'Executive approvals',audit:'Activity & data'}[t]||'Overview';}
  function header(eyebrow,heading,description,actions){return '<div class="page-header"><div><div class="eyebrow">'+safe(eyebrow)+'</div><h1>'+safe(heading)+'</h1><p>'+safe(description)+'</p></div><div class="actions">'+(actions||'')+'</div></div>'+(ui.tab==='overview'?'':screenSummary());}

  /* Summaries use the same calculated sample records displayed in each screen. */
  function meanOf(list,calculate){return list.length?Math.round(list.reduce(function(n,e){return n+calculate(e);},0)/list.length):0;}
  function metricCard(label,value,note){return '<div class="metric"><div class="metric-label">'+safe(label)+'<span class="metric-icon">◇</span></div><strong>'+safe(value)+'</strong><div class="metric-sub">'+safe(note)+'</div></div>';}
  function screenSummary(){
    const all=data.employees;
    const team=ui.tab==='division'?all.filter(function(e){return e.division===ui.activeDivision;}):all;
    let cards=[];
    if(ui.tab==='division'){
      cards=[['Division members',team.length,'Fictional employee records'],['Average KPI score',meanOf(team,score).toString()+'%','Demonstration figures only'],['Journey completion',meanOf(team,journeyPct)+'%','All 7 onboarding stages'],['Submitted evaluations',team.filter(function(e){return reviewStatus(e,'division')==='Endorsed';}).length,'Division Head endorsements']];
    }else if(ui.tab==='divisions'){
      cards=[['Active divisions',data.divisions.length,'Dedicated evaluator workspaces'],['Sample employees',all.length,'Company-wide directory'],['Average KPI score',meanOf(all,score)+'%','Demonstration scores'],['Average onboarding',meanOf(all,journeyPct)+'%','Completion across 7 stages']];
    }else if(ui.tab==='employees'){
      cards=[['Employee directory',all.length,'Fictional team members'],['Divisions',data.divisions.length,'Assigned evaluator groups'],['Average journey',meanOf(all,journeyPct)+'%','All stages'],['KPI sources to validate',all.filter(function(e){return !e.kpiValidated;}).length,'Official KPI data not connected']];
    }else if(ui.tab==='journey'){
      cards=[['Average completion',meanOf(all,journeyPct)+'%','All stages'],['Stage 1 completed',all.filter(function(e){return e.journey[0].every(Boolean);}).length,'Onboarding & setup'],['Stage 2 completed',all.filter(function(e){return e.journey[1].every(Boolean);}).length,'Onboarding & immersion'],['All 7 stages done',all.filter(function(e){return journeyPct(e)===100;}).length,'Journey complete']];
    }else if(ui.tab==='kit'){
      cards=[['Overall kit completion',meanOf(all,kitPct)+'%','All 11 checklist items'],['Fully provisioned',all.filter(function(e){return kitPct(e)===100;}).length,'Every kit item marked done'],['Pending kits',all.filter(function(e){return kitPct(e)<100;}).length,'Employee kits with open items'],['Requirements completed',all.reduce(function(n,e){return n+e.kit.filter(Boolean).length;},0),'Out of '+all.length*data.kit.length+' total']];
    }else if(ui.tab==='attendance'){
      const a=all.map(attend);
      cards=[['Verified late arrivals',a.reduce(function(n,x){return n+x.lates;},0),'Includes excused entries'],['Verified absences',a.reduce(function(n,x){return n+x.absences;},0),'Review approval reasons'],['No late / absent records',a.filter(function(x){return x.clean;}).length,'Based on verified entries'],['Employees with concerns',a.filter(function(x){return x.concerns>0;}).length,'Unexcused/unapproved verified records']];
    }else if(ui.tab==='kpi'){
      cards=[['Average weighted score',meanOf(all,score)+'%','15 / 45 / 15 / 25 grading'],['Excellent (demo)',all.filter(function(e){return score(e)>=95;}).length,'Sample score 95–100'],['Pending KPI validation',all.filter(function(e){return !e.kpiValidated;}).length,'No official KPI sync'],['Division endorsements',all.filter(function(e){return reviewStatus(e,'division')==='Endorsed';}).length,'Completed demo head reviews']];
    }else if(ui.tab==='approvals'){
      cards=[['Division Head endorsed',all.filter(function(e){return reviewStatus(e,'division')==='Endorsed';}).length,'Initial evaluation'],['Corporate Ops endorsed',all.filter(function(e){return reviewStatus(e,'corp')==='Endorsed';}).length,'Review & endorsement'],['CSO reviewed',all.filter(function(e){return reviewStatus(e,'cso')==='Endorsed';}).length,'Strategic review'],['COO approved',approvedCount(),'Final approval tracked']];
    }else if(ui.tab==='audit'){
      const changed=all.filter(function(e){return e.audit.length>0;});
      cards=[['Employee records',all.length,'All fictional'],['Edited employees',changed.length,'On this browser'],['Logged changes',all.reduce(function(n,e){return n+e.audit.length;},0),'Local activity history'],['Shared sync','Off','JSON backup available']];
    }
    return cards.length?'<section class="screen-summary" aria-label="'+safe(title(ui.tab))+' summary"><div class="summary-heading"><span class="eyebrow">SCREEN SUMMARY</span><span class="muted micro">Calculated from sample data</span></div><div class="grid metrics">'+cards.map(function(c){return metricCard(c[0],c[1],c[2]);}).join('')+'</div></section>':'';
  }
  function divisionEvaluatorNames(d){return d.evaluators.map(function(id){const v=data.viewers.find(function(p){return p.id===id;});return v?v.name:id;}).join(' / ');}
  function assignedDivisionIds(){const v=viewer();return data.divisions.filter(function(d){return d.evaluators.includes(v.id);}).map(function(d){return d.id;});}
  function divisionCard(d){
    const team=data.employees.filter(function(e){return e.division===d.id;});
    const editable=team.some(roleCanHead);
    const hr=isHR();
    const access=editable?'Department KPI editor':hr?'HR scoring available':'Observer / read-only';
    return '<article class="division-card"><div class="division-card-top"><span class="tag info">'+safe(d.short)+'</span>'+pill(editable?'Editable':hr?'HR inputs':'View only')+'</div><h2>'+safe(d.name)+'</h2><p class="division-owner">'+safe(divisionEvaluatorNames(d))+'</p><div class="division-card-stats"><span><strong>'+team.length+'</strong><small>Members</small></span><span><strong>'+meanOf(team,score)+'%</strong><small>Avg. KPI</small></span><span><strong>'+meanOf(team,journeyPct)+'%</strong><small>Journey</small></span></div><div class="division-card-footer"><span class="muted micro">'+safe(access)+'</span>'+button('Open division','goto-division','data-division="'+safe(d.id)+'"','small primary')+'</div></article>';
  }
  function divisionsView(){
    const my=assignedDivisionIds();
    const sorted=data.divisions.slice().sort(function(a,b){return Number(my.includes(b.id))-Number(my.includes(a.id));});
    return header('SEVEN DEPARTMENTS','Division workspaces','Each division has its own member list, KPI evaluation desk, assigned evaluators and live demonstration summary.',button('Employee directory','nav','data-tab="employees"','small'))+
      (my.length?'<div class="callout" style="margin-bottom:17px"><strong>Your evaluation desks:</strong> '+my.map(function(id){const d=div(id);return '<button class="link-btn" data-action="goto-division" data-division="'+safe(id)+'">'+safe(d.name)+'</button>';}).join(' &nbsp; / &nbsp; ')+'</div>':
      '<div class="callout" style="margin-bottom:17px"><strong>'+((viewer().role==='ceo'||viewer().role==='cso'||viewer().role==='coo')?'Executive observer view':'People & Culture workspace')+':</strong> Open any division to see its employee roster and report cards. Editing follows the active demonstration evaluator role.</div>')+
      '<section class="division-grid">'+sorted.map(divisionCard).join('')+'</section>';
  }
  function divisionView(){
    const d=div(ui.activeDivision);
    const team=data.employees.filter(function(e){return e.division===d.id;});
    if(!team.length)return header('DIVISION','No members found','Select another division.',button('All divisions','nav','data-tab="divisions"','small'));
    const isEditor=team.some(roleCanHead);
    const permission=isEditor?'You can edit Division and Individual Objective scores for this department.':isHR()?'You can edit HR Values Alignment and Job Behavior for employees here.':'Observer mode: you can inspect member evaluations but cannot change records.';
    const status=team.filter(function(e){return reviewStatus(e,'division')==='Endorsed';}).length;
    return header('DEPARTMENT EVALUATION',d.name,'Individual employee KPI scorecards, onboarding progress and division-specific evaluation access.',button('← All divisions','nav','data-tab="divisions"','small'))+
    '<section class="panel division-toolbar"><div class="division-toolbar-row"><div class="division-heading"><span class="eyebrow">ASSIGNED EVALUATOR'+(d.evaluators.length>1?'S':'')+'</span><h2>'+safe(divisionEvaluatorNames(d))+'</h2><p class="muted micro">'+safe(permission)+'</p></div><div class="division-switch"><label class="field-label" for="division-switch">Switch division</label><select class="field" id="division-switch" data-ui="activeDivision">'+opts(data.divisions.map(function(v){return {value:v.id,label:v.name};}),d.id)+'</select></div></div></section>'+
    '<section class="panel no-pad"><div class="table-wrap"><table class="table division-members"><thead><tr><th>Team member</th><th>Division KPI · 15%</th><th>Individual KPI · 45%</th><th>HR grading · 40%</th><th>Overall</th><th>Review status</th><th>Evaluation</th></tr></thead><tbody>'+
    team.map(function(e){return '<tr><td><div class="name-cell">'+avatar(e.name)+'<div><strong>'+safe(e.name)+'</strong><small>'+safe(e.id)+' · '+safe(e.jobTitle)+'</small></div></div></td><td><strong>'+e.scores.division.toFixed(1)+'%</strong></td><td><strong>'+e.scores.individual.toFixed(1)+'%</strong></td><td><strong>'+((e.scores.values*.15+e.scores.behavior*.25)/.4).toFixed(1)+'%</strong></td><td><strong class="score">'+score(e).toFixed(1)+'%</strong><small>'+safe(rating(score(e)))+'</small></td><td>'+pill(reviewStatus(e,'division'))+'</td><td><div class="actions">'+button(isEditor||isHR()?'Evaluate':'View report','open','data-id="'+safe(e.id)+'" data-detail="kpi"','small primary')+button('Journey','open','data-id="'+safe(e.id)+'" data-detail="journey"','small')+'</div></td></tr>';}).join('')+
    '</tbody></table></div></section><div class="division-hint">This division has '+team.length+' fictional employee profiles; '+status+' have a completed Division Head endorsement. Ratings are generated from sample scores, not official KPI records.</div>';
  }
  function quickDivisionAccess(){
    const ids=assignedDivisionIds();
    if(!ids.length)return '';
    return '<section class="panel assigned-panel"><div class="heading-line"><div><h2>My division evaluation desk'+(ids.length>1?'s':'')+'</h2><p class="muted micro">Open your assigned members and their KPI scorecards</p></div>'+button('All divisions','nav','data-tab="divisions"','small')+'</div><div class="assigned-links">'+ids.map(function(id){const d=div(id);const team=data.employees.filter(function(e){return e.division===id;});return button(safe(d.name)+' · '+team.length+' members','goto-division','data-division="'+safe(id)+'"','primary');}).join('')+'</div></section>';
  }
  function metrics(){return '<div class="grid metrics"><div class="metric"><div class="metric-label">Team members <span class="metric-icon">◎</span></div><strong>'+data.employees.length+'</strong><div class="metric-sub">Across '+data.divisions.length+' divisions · demo</div></div><div class="metric"><div class="metric-label">Journey completion <span class="metric-icon">◷</span></div><strong>'+totalAvg(journeyPct)+'%</strong><div class="metric-sub">All 7 stages · sample progress</div></div><div class="metric"><div class="metric-label">Welcome kit ready <span class="metric-icon">▣</span></div><strong>'+totalAvg(kitPct)+'%</strong><div class="metric-sub">Equipment, tools & access</div></div><div class="metric"><div class="metric-label">Approval completed <span class="metric-icon">✓</span></div><strong>'+approvedCount()+' / 51</strong><div class="metric-sub">'+pendingCount()+' not fully approved</div></div></div>';}
  function overview(){
    const leaders=data.divisions.map(function(d){const es=data.employees.filter(function(e){return e.division===d.id;});return '<div class="bar-line"><span>'+safe(d.short)+'</span>'+progress(Math.round(es.reduce(function(a,e){return a+journeyPct(e);},0)/es.length))+'<strong>'+Math.round(es.reduce(function(a,e){return a+journeyPct(e);},0)/es.length)+'%</strong></div>';}).join('');
    const concern=data.employees.slice().sort(function(a,b){return attend(b).concerns-attend(a).concerns;}).filter(function(e){return attend(e).concerns>0;}).slice(0,4);
    const soon=data.employees.filter(function(e){return journeyPct(e)<45;}).slice(0,4);
    return header('A CLEARER WAY TO WORK','Good to see you.','One workspace for 51 sample Maddies — onboarding, attendance, KPI reviews and approvals.',button('View directory','nav','data-tab="employees"','primary'))
    +metrics()+quickDivisionAccess()+'<div class="grid dashboard-grid"><section class="panel"><div class="panel-head"><div><h2>Onboarding across divisions</h2><p>Average completion of all journey-stage requirements</p></div>'+pill('Demo')+'</div>'+leaders+'</section><section class="panel"><div class="panel-head"><div><h2>Management snapshot</h2><p>Verified attendance records only</p></div></div><div class="grid" style="grid-template-columns:1fr 1fr;gap:12px"><div class="soft"><span class="muted micro">Employees with late records</span><h2>'+data.employees.filter(function(e){return attend(e).lates>0;}).length+'</h2></div><div class="soft"><span class="muted micro">Employees with absences</span><h2>'+data.employees.filter(function(e){return attend(e).absences>0;}).length+'</h2></div><div class="soft"><span class="muted micro">No lates or absences</span><h2>'+data.employees.filter(function(e){return attend(e).clean;}).length+'</h2></div><div class="soft"><span class="muted micro">Pending final approval</span><h2>'+pendingCount()+'</h2></div></div><div class="hr"></div><div class="callout"><strong>Role preview:</strong> Switch evaluators in the upper-right corner to test each part of the approval process. Role restrictions here are UI simulations, not real authorization.</div></section></div>'
    +'<div class="grid subgrid"><section class="panel"><div class="panel-head"><div><h2>Onboarding needs attention</h2><p>Employees with lower sample journey completion</p></div>'+button('Open journey','nav','data-tab="journey"','small')+'</div><div class="quick-list">'+soon.map(function(e){return '<div class="quick-item">'+avatar(e.name)+'<div class="grow"><b>'+safe(e.name)+'</b><p>'+safe(div(e.division).short)+' · '+journeyPct(e)+'% completed</p></div>'+button('Open','open','data-id="'+e.id+'"','small')+'</div>';}).join('')+'</div></section><section class="panel"><div class="panel-head"><div><h2>Attendance signals</h2><p>Unexcused or unapproved verified incidents</p></div>'+button('See analytics','nav','data-tab="attendance"','small')+'</div><div class="quick-list">'+concern.map(function(e){return '<div class="quick-item">'+avatar(e.name)+'<div class="grow"><b>'+safe(e.name)+'</b><p>'+safe(div(e.division).short)+' · '+attend(e).concerns+' concern(s)</p></div>'+button('Review','open','data-id="'+e.id+'" data-detail="attendance"','small')+'</div>';}).join('')+'</div></section></div>';
  }
  function employeesTable(list,mode){if(!list.length)return '<div class="empty"><span class="big">⌕</span>No employees match these filters.</div>';
    return '<div class="table-wrap"><table class="table"><thead><tr><th>Employee</th><th>Division</th><th>Journey</th><th>Kit issued</th><th>KPI score</th><th>Actions</th></tr></thead><tbody>'+list.map(function(e){return '<tr><td><div class="name-cell">'+avatar(e.name)+'<div><strong>'+safe(e.name)+'</strong><small>'+safe(e.id)+' · '+safe(e.jobTitle)+'</small></div></div></td><td>'+safe(div(e.division).short)+'</td><td><div class="progress-wrapper">'+progress(journeyPct(e))+'<span>'+journeyPct(e)+'%</span></div></td><td>'+kitPct(e)+'%</td><td><strong>'+score(e).toFixed(1)+'%</strong><small>'+rating(score(e))+'</small></td><td>'+button('Open profile','open','data-id="'+e.id+'" '+(mode?'data-detail="'+mode+'"':''),'small')+'</td></tr>';}).join('')+'</tbody></table></div>';}
  function filtered(){return data.employees.filter(function(e){return (ui.division==='all'||e.division===ui.division)&&(!ui.query||(e.name+' '+e.id+' '+e.jobTitle+' '+div(e.division).name).toLowerCase().includes(ui.query.toLowerCase()));});}
  function filters(){return '<div class="filters"><input type="search" class="search" aria-label="Search employees" data-ui="query" placeholder="Search by name, role or employee ID..." value="'+safe(ui.query)+'"><select class="field filter-select" aria-label="Filter by division" data-ui="division">'+opts([{value:'all',label:'All divisions'}].concat(data.divisions.map(function(d){return {value:d.id,label:d.name};})),ui.division)+'</select><span class="muted micro">'+filtered().length+' employees</span></div>';}
  function employees(){return header('PEOPLE DIRECTORY','All Maddies','Browse and edit a fictional 51-person roster across the seven assigned divisions.',button('Export CSV','export-csv','','small')+' '+button('Download backup','export','','small'))+'<section class="panel no-pad"><div style="padding:20px 20px 0">'+filters()+'</div>'+employeesTable(filtered())+'</section>';}
  function stageCards(e){return '<div class="grid step-grid">'+data.stages.map(function(s,si){let done=e.journey[si].filter(Boolean).length;return '<div class="step-card"><div class="step-title"><div><div class="step-number">STAGE '+(si+1)+' · '+safe(s.timing)+'</div><h3>'+safe(s.name)+'</h3></div><span class="tag '+(done===s.items.length?'ok':'warn')+'">'+done+'/'+s.items.length+'</span></div>'+progress(Math.round(done/s.items.length*100))+'<div style="margin-top:10px">'+s.items.map(function(item,ii){return '<label class="check-row '+(canTrack(e)?'':'disabled')+'"><input type="checkbox" data-stage="'+si+'" data-item="'+ii+'" '+(e.journey[si][ii]?'checked ':'')+(canTrack(e)?'':'disabled ')+'><span>'+safe(item)+'</span></label>';}).join('')+'</div></div>';}).join('')+'</div>';}
  function employeeSelector(){const e=emp();return '<label class="field-label" for="employee-picker">Selected employee</label><select id="employee-picker" class="field" data-ui="employee">'+opts(data.employees.map(function(p){return {value:p.id,label:p.name+' — '+div(p.division).short};}),e.id)+'</select>';}
  function journey(){let e=emp();return header('SEVEN STAGES','Journey tracker','Standardized checklist from onboarding through regularization and development.',button('View profile','open','data-id="'+e.id+'" data-detail="journey"','small'))+'<div class="grid dashboard-grid"><section class="panel"><div class="panel-head"><div><h2>Employee progress</h2><p>Track individual tasks and approvals</p></div><span class="tag info">'+journeyPct(e)+'% complete</span></div>'+employeeSelector()+'<div style="margin-top:13px">'+progress(journeyPct(e))+'</div><p class="muted micro" style="margin-top:10px">Only HR and the assigned division evaluators can edit checklist items in this demonstration.</p></section><section class="panel"><h2>Initial onboarding priority</h2><p class="muted micro" style="margin:9px 0 18px">Stage 1 & Stage 2 form the standard onboarding process for incoming employees.</p><div class="bar-line"><span>Stage 1</span>'+progress(Math.round(e.journey[0].filter(Boolean).length/e.journey[0].length*100))+'<strong>'+e.journey[0].filter(Boolean).length+'/'+e.journey[0].length+'</strong></div><div class="bar-line"><span>Stage 2</span>'+progress(Math.round(e.journey[1].filter(Boolean).length/e.journey[1].length*100))+'<strong>'+e.journey[1].filter(Boolean).length+'/'+e.journey[1].length+'</strong></div></section></div>'+stageCards(e);}
  function kitSection(e){return '<div class="kit-grid">'+data.kit.map(function(k,i){return '<div class="kit-item"><label class="check-row '+(canTrack(e)?'':'disabled')+'"><input type="checkbox" data-kit="'+i+'" '+(e.kit[i]?'checked ':'')+(canTrack(e)?'':'disabled ')+'><strong>'+safe(k.label)+'</strong></label><label class="field-label">'+(k.type==='equipment'?'Item / issuance details':'Setup / access notes')+'</label>'+input('kitnote.'+k.id,e.kitNotes[k.id]||'',{disabled:!canTrack(e),placeholder:'Reference or status only — never passwords'})+'</div>';}).join('')+'</div>';}
  function kitView(){const e=emp();return header('ONBOARDING INVENTORY','Welcome Maddie Kit','Individual tracking for equipment, accounts, tools and community access.',button('View profile','open','data-id="'+e.id+'" data-detail="kit"','small'))+'<div class="grid dashboard-grid"><section class="panel"><h2>Employee and kit progress</h2><div class="hr"></div>'+employeeSelector()+'<div style="margin-top:15px">'+progress(kitPct(e))+'</div><p class="muted micro" style="margin-top:10px">'+e.kit.filter(Boolean).length+' of '+data.kit.length+' requirements completed</p></section><section class="panel"><div class="callout orange"><strong>Access notes are not credentials.</strong> Store only tool names, issuance references and completion statuses. Never put employee passwords, API tokens or private access keys in the prototype.</div><div class="hr"></div><span class="muted micro">Equipment: laptop, uniform, ID · Software: ChatGPT, Claude and division apps · Access: email, WhatsApp and community groups</span></section></div>'+kitSection(e);}
  function frequencyRecords(e){return e.attendance.slice().filter(function(r){return r.verified;}).sort(function(a,b){return b.date.localeCompare(a.date);});}
  function attendanceSummary(e){const a=attend(e);return '<div class="grid metrics"><div class="metric"><div class="metric-label">Verified late arrivals</div><strong>'+a.lates+'</strong><div class="metric-sub">Last: '+dateLabel(a.lastLate)+'</div></div><div class="metric"><div class="metric-label">Verified absences</div><strong>'+a.absences+'</strong><div class="metric-sub">Last: '+dateLabel(a.lastAbs)+'</div></div><div class="metric"><div class="metric-label">Attendance concerns</div><strong>'+a.concerns+'</strong><div class="metric-sub">Excused late entries excluded</div></div><div class="metric"><div class="metric-label">Attendance status</div><strong style="font-size:21px">'+(a.records.length?'With records':'No record')+'</strong><div class="metric-sub">Only verified entries are counted</div></div></div>';}
  function attendanceRows(e){const rs=e.attendance.slice().sort(function(a,b){return b.date.localeCompare(a.date);});return '<div class="table-wrap"><table class="table"><thead><tr><th>Date</th><th>Type</th><th>Approval</th><th>Verification</th><th>Reason / remarks</th><th></th></tr></thead><tbody>'+rs.map(function(r){return '<tr><td>'+dateLabel(r.date)+'</td><td><strong>'+safe(r.type)+'</strong></td><td>'+pill(r.approval)+'</td><td>'+pill(r.verified?'Verified':'Pending')+'</td><td><strong>'+safe(r.reason)+'</strong><small>'+safe(r.remarks)+'</small></td><td>'+(isHR()?button('Edit','edit-record','data-id="'+safe(r.id)+'"','small'):'')+'</td></tr>';}).join('')+'</tbody></table></div>';}
  function series(){const months=[];const dt=new Date();dt.setDate(1);for(let i=5;i>=0;i--){const d=new Date(dt.getFullYear(),dt.getMonth()-i,1);const key=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0');let late=0,abs=0;data.employees.forEach(function(e){e.attendance.forEach(function(r){if(r.verified&&r.date.slice(0,7)===key){if(r.type==='Late')late++;if(r.type==='Absent')abs++;}});});months.push({label:d.toLocaleDateString('en-PH',{month:'short'}),late:late,abs:abs});}return months;}
  function chart(){const s=series(),max=Math.max(1,...s.map(function(x){return x.late+x.abs;}));return '<div class="mini-bars">'+s.map(function(m){return '<div title="'+m.label+': '+m.late+' late, '+m.abs+' absent"><span style="height:'+Math.max(3,Math.round((m.late+m.abs)/max*92))+'px"></span>'+m.label+'</div>';}).join('')+'</div><p class="muted micro" style="margin-top:12px">Last 6 months · late and absence records · verified only</p>';}
  function rankRows(type){const ranked=data.employees.map(function(e){return {e:e,n:attend(e)[type]};}).filter(function(v){return v.n>0;}).sort(function(a,b){return b.n-a.n;}).slice(0,5);return ranked.length?ranked.map(function(v,i){return '<div class="rank"><span class="rank-index">'+(i+1)+'</span><div><b>'+linkedEmployee(v.e)+'</b><p class="muted micro">'+safe(div(v.e.division).short)+'</p></div><span class="count">'+v.n+'</span></div>';}).join(''):'<p class="muted">No verified entries</p>';}
  function attendancePeriodTable(){const buckets={};data.employees.forEach(function(e){e.attendance.forEach(function(r){if(!r.verified)return;let period=r.date.slice(0,7);if(ui.frequency==='weekly'){const d=new Date(r.date+'T00:00:00Z');d.setUTCDate(d.getUTCDate()-((d.getUTCDay()+6)%7));period=d.toISOString().slice(0,10);}if(!buckets[period])buckets[period]={late:0,absent:0,approved:0,excused:0};if(r.type==='Late'){buckets[period].late++;if(r.approval==='Excused')buckets[period].excused++;}if(r.type==='Absent')buckets[period].absent++;if(r.type==='Leave'&&r.approval==='Approved')buckets[period].approved++;});});const keys=Object.keys(buckets).sort().reverse().slice(0,12);return '<section class="panel" style="margin-top:17px"><div class="panel-head"><div><h2>Weekly & monthly summary</h2><p>Verified records only; approved leave and excused lateness are displayed separately</p></div><select class="field" style="max-width:150px" aria-label="Attendance summary frequency" data-ui="frequency">'+opts([{value:'weekly',label:'Weekly'},{value:'monthly',label:'Monthly'}],ui.frequency)+'</select></div><div class="table-wrap"><table class="table"><thead><tr><th>Period</th><th>Late arrivals</th><th>Absences</th><th>Excused lates</th><th>Approved leaves</th></tr></thead><tbody>'+(keys.length?keys.map(function(k){const b=buckets[k];return '<tr><td><strong>'+safe(k)+'</strong></td><td>'+b.late+'</td><td>'+b.absent+'</td><td>'+b.excused+'</td><td>'+b.approved+'</td></tr>';}).join(''):'<tr><td colspan="5">No verified records for this frequency.</td></tr>')+'</tbody></table></div></section>';}
  function attendanceView(){const e=emp();return header('PEOPLE ANALYTICS','Attendance monitoring','Verified late arrivals, absences, approvals and recurring patterns. Approved leaves are not automatically violations.',button('Export attendance','attendance-csv','','small'))+'<div class="grid dashboard-grid"><section class="panel"><div class="panel-head"><div><h2>Recent attendance trend</h2><p>Verified records across all 51 demo employees</p></div></div>'+chart()+'</section><section class="panel"><div class="panel-head"><div><h2>Employee attendance</h2><p>Select a profile to inspect detailed records</p></div></div>'+employeeSelector()+'<div class="hr"></div><div class="actions">'+button('Add attendance entry','new-record','',isHR()?'primary':'')+'</div><p class="muted micro" style="margin-top:9px">'+(isHR()?'HR role can record and verify an entry.':'Switch to an HR demo role to add an entry.')+'</p></section></div><div class="grid subgrid" style="margin-bottom:18px"><section class="panel"><div class="panel-head"><h2>Most verified late arrivals</h2></div>'+rankRows('lates')+'</section><section class="panel"><div class="panel-head"><h2>Most verified absences</h2></div>'+rankRows('absences')+'</section></div><section class="panel"><div class="panel-head"><div><h2>'+safe(e.name)+' · attendance history</h2><p>Includes pending/unverified entries, but only verified data appears in summaries and rankings</p></div></div>'+attendanceSummary(e)+attendanceRows(e)+'</section>'+attendancePeriodTable();}
  function scoresPanel(e){const categories=[['division','I. Division objectives',15,'Division Head'],['individual','II. Individual objectives',45,'Division Head'],['values','III. Values alignment',15,'HR / P&C'],['behavior','IV. Job behavior',25,'HR / P&C']];return '<div class="score-weights">'+categories.map(function(cat){const can=canScore(e,cat[0]);return '<div class="score-block '+(can?'':'locked')+'"><div class="heading-line"><span class="muted micro">'+cat[2]+'% weight</span>'+pill(can?'Editable':'View only')+'</div><h3>'+cat[1]+'</h3><p class="muted micro" style="margin:5px 0 12px">'+cat[3]+'</p><label class="field-label">Score (0–100)</label>'+input('score.'+cat[0],e.scores[cat[0]],{type:'number',min:0,max:100,step:0.1,disabled:!can})+'<p class="muted micro" style="margin-top:9px">Weighted: '+(e.scores[cat[0]]*cat[2]/100).toFixed(2)+' points</p></div>';}).join('')+'</div>';}
  function kpiDetail(e){const s=score(e),can=roleCanHead(e);return '<div class="grid dashboard-grid"><section class="panel"><div class="panel-head"><div><h2>Weighted evaluation</h2><p>15% + 45% + 15% + 25% = 100%</p></div>'+pill(rating(s))+'</div><div class="big-score">'+s.toFixed(2)+'%</div><div class="score-meter" aria-label="Category weights 15 45 15 25"><span></span><span></span><span></span><span></span></div><p class="muted micro" style="margin-top:11px">Demonstration scoring; no official 2026 KPI sheets are imported.</p></section><section class="panel"><h2>Official KPI source</h2><div class="hr"></div>'+pill(e.kpiValidated?'Validated':'Needs validation')+'<p class="muted micro" style="margin-top:12px">'+input('kpiSource',e.kpiSource,{disabled:!isHR()})+'</p><div class="callout orange" style="margin-top:14px">Placeholder targets and accomplishments are sample data, not verified employee goals. Validate against each official KPI sheet before real use.</div></section></div>'+scoresPanel(e)+'<section class="panel" style="margin-top:16px"><div class="panel-head"><div><h2>Employee objectives & accomplishments</h2><p>Editable placeholders for demonstration; official source remains unverified</p></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Objective</th><th>Target</th><th>Actual</th><th>Validation</th></tr></thead><tbody>'+e.kpiItems.map(function(k,i){return '<tr><td>'+safe(k.title)+'</td><td>'+input('kpi.'+i+'.target',k.target,{disabled:!can})+'</td><td>'+input('kpi.'+i+'.actual',k.actual,{disabled:!can})+'</td><td>'+pill(k.verified?'Verified':'Sample')+'</td></tr>';}).join('')+'</tbody></table></div><div class="hr"></div><div class="form-grid"><div><label class="field-label">Division Head comments</label>'+textArea('comment.division',e.comments.division,!can)+'</div><div><label class="field-label">HR assessment</label>'+textArea('comment.hr',e.comments.hr,!isHR())+'</div></div></section>';}
  function kpiView(){const e=emp();return header('2026 ANNUAL EVALUATION','KPI scorecards','Division objectives, individual KPIs, values and job behavior in one weighted evaluation.',button('Open full review','open','data-id="'+e.id+'" data-detail="approvals"','small'))+'<section class="panel" style="margin-bottom:17px"><div class="form-grid"><div>'+employeeSelector()+'</div><div><label class="field-label">Assigned evaluator(s)</label><div class="soft" style="font-size:12px">'+safe(div(e.division).evaluators.map(function(id){const v=data.viewers.find(function(p){return p.id===id;});return v?v.name:id;}).join(' / '))+'</div></div></div></section>'+kpiDetail(e);}
  function reviewStatus(e,k){return e.review[k]&&e.review[k].status||'Pending';}
  function reviewCanAct(e,k){if(k==='division')return roleCanHead(e);if(k==='corp')return canReview('corp')&&reviewStatus(e,'division')==='Endorsed';if(k==='cso')return canReview('cso')&&reviewStatus(e,'corp')==='Endorsed';if(k==='coo')return canReview('coo')&&reviewStatus(e,'cso')==='Endorsed';return false;}
  function compensation(e){const base=Number(e.currentBasic)||0,allow=Number(e.currentAllowances)||0,proposal=Number(e.proposedPct)||0,approved=Number(e.approvedPct)||0;return '<div class="money-grid"><div class="money-stat"><span>Current basic salary · demo</span><strong>'+money(base)+'</strong></div><div class="money-stat"><span>Current gross · demo</span><strong>'+money(base+allow)+'</strong></div><div class="money-stat"><span>Proposed increase</span><strong>'+money(base*proposal/100)+' ('+proposal+'%)</strong></div><div class="money-stat"><span>Proposed new gross</span><strong>'+money(base*(1+proposal/100)+allow)+'</strong></div><div class="money-stat"><span>Approved increase</span><strong>'+money(base*approved/100)+' ('+approved+'%)</strong></div><div class="money-stat"><span>Approved new basic</span><strong>'+money(base*(1+approved/100))+'</strong></div><div class="money-stat"><span>Approved new gross</span><strong>'+money(base*(1+approved/100)+allow)+'</strong></div><div class="money-stat"><span>Effectivity date</span><strong>'+dateLabel(e.effectiveDate)+'</strong></div></div>';}
  function reviewFlow(e){const steps=[['division','01','Division Head · Initial evaluation','Division objectives, KPI scoring and salary proposal'],['corp','02','Corporate Operations · Endorsement','Validate the recommendation and organizational contribution'],['cso','03','CSO · Strategic review','Alignment with strategy and contribution'],['coo','04','COO · Final approval','Confirm increase, final amount and effectivity']];return '<div class="review-steps">'+steps.map(function(s){const key=s[0],status=reviewStatus(e,key),can=reviewCanAct(e,key);return '<div class="review-step '+(status==='Approved'||status==='Endorsed'?'complete':'')+'"><div class="step-bubble">'+s[1]+'</div><div><h3>'+safe(s[2])+'</h3><p class="note">'+safe(s[3])+'</p>'+pill(status)+'<p class="muted micro" style="margin-top:7px">'+safe(e.review[key].comment||'No review note yet.')+'</p>'+(e.review[key].at?'<p class="muted micro">Updated '+safe(dateLabel(e.review[key].at.slice(0,10)))+'</p>':'')+'</div><div class="actions">'+(can?button(key==='coo'?'Approve':'Endorse','review','data-step="'+key+'" data-decision="'+(key==='coo'?'Approved':'Endorsed')+'"','small primary')+(key==='division'?'':button('Return','review','data-step="'+key+'" data-decision="Returned"','small')):'')+'</div></div>';}).join('')+'</div>';}
  function approvalsDetail(e){const canHead=roleCanHead(e),canCoo=false;return '<section class="panel" style="margin-bottom:16px"><div class="panel-head"><div><h2>Compensation proposal and approval</h2><p>All currency figures below are fictional demonstration values.</p></div>'+pill(reviewStatus(e,'coo'))+'</div>'+compensation(e)+'<div class="hr"></div><div class="form-grid"><div><label class="field-label">Current basic salary (₱)</label>'+input('currentBasic',e.currentBasic,{type:'number',min:0,step:1,disabled:!canHead})+'</div><div><label class="field-label">Allowances (₱)</label>'+input('currentAllowances',e.currentAllowances,{type:'number',min:0,step:1,disabled:!canHead})+'</div><div><label class="field-label">Division Head proposed increase (%)</label>'+input('proposedPct',e.proposedPct,{type:'number',min:0,max:100,step:0.01,disabled:!canHead})+'</div><div><label class="field-label">COO approved increase (%)</label>'+input('approvedPct',e.approvedPct,{type:'number',min:0,max:100,step:0.01,disabled:!canCoo})+'</div><div><label class="field-label">Effectivity date</label>'+input('effectiveDate',e.effectiveDate,{type:'date',disabled:!canCoo})+'</div><div><label class="field-label">Employee acknowledgment</label>'+input('comment.employee',e.comments.employee,{disabled:!isHR(),placeholder:'Recorded by HR after acknowledgment'})+'</div></div></section><section class="panel"><div class="panel-head"><div><h2>Executive approval workflow</h2><p>Each step requires the preceding endorsement</p></div></div>'+reviewFlow(e)+'<div class="hr"></div><div class="form-grid"><div><label class="field-label">Corporate Operations comments</label>'+textArea('comment.corp',e.comments.corp,viewer().role!=='corp')+'</div><div><label class="field-label">CSO comments</label>'+textArea('comment.cso',e.comments.cso,true)+'</div><div><label class="field-label">COO final remarks</label>'+textArea('comment.coo',e.comments.coo,!canCoo)+'</div><div><label class="field-label">Division Head recommendation</label>'+textArea('comment.division',e.comments.division,!canHead)+'</div></div></section>';}
  function approvalsTable(){return '<section class="panel" style="margin-top:18px"><div class="panel-head"><div><h2>Company-wide review queue</h2><p>All 51 fictional employees and current approval milestones</p></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Employee</th><th>Division</th><th>Division Head</th><th>Corporate Ops</th><th>CSO</th><th>COO</th><th></th></tr></thead><tbody>'+data.employees.map(function(e){return '<tr><td>'+linkedEmployee(e)+'</td><td>'+safe(div(e.division).short)+'</td><td>'+pill(reviewStatus(e,'division'))+'</td><td>'+pill(reviewStatus(e,'corp'))+'</td><td>'+pill(reviewStatus(e,'cso'))+'</td><td>'+pill(reviewStatus(e,'coo'))+'</td><td>'+button('Review','open','data-id="'+e.id+'" data-detail="approvals"','small')+'</td></tr>';}).join('')+'</tbody></table></div></section>';}
  function approvalsView(){const e=emp();return header('REVIEW & GOVERNANCE','Executive approvals','Division Head → Corporate Operations → CSO → COO, with comments and separate proposed versus approved compensation.',button('See KPI scorecard','nav','data-tab="kpi"','small'))+'<section class="panel" style="margin-bottom:16px"><div class="form-grid"><div>'+employeeSelector()+'</div><div><label class="field-label">Final approval status</label><div style="padding:7px 0">'+pill(reviewStatus(e,'coo'))+' <span class="muted micro"> · '+safe(div(e.division).name)+'</span></div></div></div></section>'+approvalPolicy()+approvalsDetail(e)+approvalsTable();}
  function activity(){const logs=[];data.employees.forEach(function(e){(e.audit||[]).forEach(function(a){logs.push({date:a.date,employee:e.name,actor:a.actor,action:a.action});});});logs.sort(function(a,b){return b.date.localeCompare(a.date);});return header('WORKSPACE SETTINGS','Activity & data','Review local changes and manage your demonstration dataset.',button('Download JSON backup','export','','primary'))+'<div class="grid dashboard-grid"><section class="panel"><h2>Data controls</h2><p class="muted micro" style="margin:8px 0 17px">Edits are saved to this browser only. They do not automatically sync across devices or evaluators.</p><div class="actions">'+button('Export all data (JSON)','export','','small')+button('Import backup','import','','small')+button('Download employee CSV','export-csv','','small')+button('Reset 51 sample employees','reset','','small danger')+'</div><input type="file" id="import-file" accept=".json,application/json" hidden><div class="hr"></div><div class="callout orange"><strong>Privacy & security:</strong> This is a public-repository prototype with simulated role permissions. It is not suitable for live employee, confidential compensation, or authentication data. Use a secure backend and verified access controls before any production rollout.</div></section><section class="panel"><h2>Assigned evaluators</h2><p class="muted micro" style="margin:7px 0 16px">Current roster per project instruction</p>'+data.divisions.map(function(d){return '<div class="quick-item"><div class="grow"><b>'+safe(d.name)+'</b><p>'+safe(d.evaluators.map(function(id){const v=data.viewers.find(function(p){return p.id===id;});return v?v.name:id;}).join(' / '))+'</p></div></div>';}).join('')+'<div class="hr"></div><p class="muted micro">HR: GIEZELLE · KURT</p></section></div><section class="panel"><div class="panel-head"><div><h2>Local activity log</h2><p>Actions recorded in this browser by the selected demo viewer</p></div><span class="tag info">'+logs.length+' events</span></div><div class="audit-list">'+(logs.length?logs.slice(0,60).map(function(a){return '<div class="audit-row"><span class="avatar">↗</span><div><p><strong>'+safe(a.actor)+'</strong> · '+safe(a.action)+'</p><small>'+safe(a.employee)+' · '+safe(new Date(a.date).toLocaleString('en-PH'))+'</small></div></div>';}).join(''):'<div class="empty">No edits recorded yet. Edit any sample entry to see its audit trail.</div>')+'</div></section>';}
  function detailContent(e,t){if(t==='journey')return '<div class="panel"><div class="panel-head"><h2>Seven-stage checklist</h2><span class="tag info">'+journeyPct(e)+'% done</span></div>'+stageCards(e)+'</div>';if(t==='kit')return '<div class="panel"><div class="panel-head"><h2>Welcome Maddie Kit</h2><span class="tag info">'+kitPct(e)+'% ready</span></div>'+kitSection(e)+'</div>';if(t==='attendance')return '<section class="panel">'+attendanceSummary(e)+'<div class="hr"></div>'+attendanceRows(e)+'</section>';if(t==='kpi')return kpiDetail(e);if(t==='approvals')return approvalsDetail(e);return '';}
  function profileForm(e){const edit=isHR();return '<details class="panel" style="margin-bottom:14px"><summary style="font-size:12px;font-weight:800;cursor:pointer">Employee information '+(edit?'· HR editable':'· view only')+'</summary><div class="form-grid" style="margin-top:18px"><div><label class="field-label">Full name</label>'+input('profile.name',e.name,{disabled:!edit})+'</div><div><label class="field-label">Job title</label>'+input('profile.jobTitle',e.jobTitle,{disabled:!edit})+'</div><div><label class="field-label">Demo email</label>'+input('profile.email',e.email,{disabled:!edit,type:'email'})+'</div><div><label class="field-label">Start date</label>'+input('profile.startDate',e.startDate,{disabled:!edit,type:'date'})+'</div><div class="span2"><label class="field-label">Assigned division</label>'+select('profile.division',e.division,data.divisions.map(function(d){return {label:d.name,value:d.id};}),!edit)+'</div></div></details>';}
  function employeeMini(e){const a=attend(e);return '<div class="employee-mini-summary" aria-label="Employee summary"><span><small>Journey</small><strong>'+journeyPct(e)+'%</strong></span><span><small>Welcome kit</small><strong>'+kitPct(e)+'%</strong></span><span><small>Weighted KPI</small><strong>'+score(e).toFixed(1)+'%</strong></span><span><small>Verified lates / absences</small><strong>'+a.lates+' / '+a.absences+'</strong></span></div>';}
  function approvalPolicy(){const v=viewer();const exec=['ceo','cso','coo'].includes(v.role);return '<div class="callout '+(exec?'':'orange')+'" style="margin-bottom:16px"><strong>'+(exec?'Executive observer mode.':'Workflow demonstration.')+'</strong> Division Heads can submit evaluations for their departments; Corporate Operations can enter review endorsements. CEO, CSO and COO views are read-only in this update. Executive final approvals shown here are fictional sample records, not editable decisions.</div>';}
  function drawer(){const e=emp(),t=ui.detail;return '<div class="overlay" data-overlay="true"><aside class="drawer" role="dialog" aria-modal="true" aria-label="Employee profile"><div class="drawer-top"><span class="eyebrow">EMPLOYEE PROFILE · '+safe(e.id)+'</span><button class="drawer-close" type="button" aria-label="Close profile" data-action="close">×</button></div><div class="employee-head"><div class="profile">'+avatar(e.name)+'<div><h2>'+safe(e.name)+'</h2><p class="muted micro">'+safe(e.jobTitle)+' · '+safe(div(e.division).name)+'</p><p class="muted micro">Started '+dateLabel(e.startDate)+' · '+safe(e.email)+'</p></div></div>'+pill(rating(score(e)))+'</div>'+employeeMini(e)+profileForm(e)+'<div class="tabbar">'+[['journey','Journey'],['kit','Welcome kit'],['attendance','Attendance'],['kpi','KPI score'],['approvals','Approvals']].map(function(a){return '<button class="tab '+(t===a[0]?'active':'')+'" data-action="detail" data-tab="'+a[0]+'">'+a[1]+'</button>';}).join('')+'</div>'+detailContent(e,t)+'</aside></div>';}
  function render(){const views={overview:overview,divisions:divisionsView,division:divisionView,employees:employees,journey:journey,kit:kitView,attendance:attendanceView,kpi:kpiView,approvals:approvalsView,audit:activity};$('app').innerHTML='<div class="layout '+(ui.mobile?'menu-open':'')+'">'+sidebar()+'<main class="main">'+topnav()+(views[ui.tab]||overview)()+'<footer class="footer"><span>Maddie Journey · Prototype v1.0</span><span>51 fictional employees · Local browser storage · No live integrations</span></footer></main></div>'+(ui.drawer?drawer():'');document.title=title(ui.tab)+' · Maddie Journey';}
  function openDivision(id){if(!data.divisions.some(function(d){return d.id===id;}))return;ui.activeDivision=id;ui.tab='division';ui.drawer=false;ui.mobile=false;ui.query='';ui.division='all';if(location.hash!=='#division/'+id)location.hash='#division/'+id;window.scrollTo({top:0,behavior:'instant'});render();}
  function navigate(tab){if(tab==='division'){openDivision(ui.activeDivision);return;}ui.tab=tab;ui.drawer=false;ui.mobile=false;ui.query='';ui.division='all';if(location.hash!=='#'+tab)location.hash='#'+tab;window.scrollTo({top:0,behavior:'instant'});render();}
  function invalidateEvaluation(e){
    const changed=['division','corp','cso','coo'].some(function(k){return e.review[k].status!=='Pending';})||e.approvedPct>0||!!e.effectiveDate;
    if(!changed)return;
    ['division','corp','cso','coo'].forEach(function(k){e.review[k]={status:'Pending',comment:'',at:''};});
    e.approvedPct=0;e.effectiveDate='';
    toast('Evaluation changed: previous review endorsements were reset.');
  }
  function changeField(el){const e=emp(),field=el.dataset.field;if(!e||!field)return;const val=el.value;
    if(field.indexOf('profile.')===0){if(!isHR())return;const k=field.slice(8);if(!['name','jobTitle','email','startDate','division'].includes(k))return;if((k==='name'||k==='jobTitle')&&!val.trim()){toast('This field cannot be empty.');render();return;}if(k==='division'&&!data.divisions.some(function(d){return d.id===val;}))return;e[k]=val.slice(0,150);if(k==='division')invalidateEvaluation(e);audit(e,'Updated employee '+k);}
    else if(field.indexOf('kpi.')===0){if(!roleCanHead(e))return;const parts=field.split('.'),i=Number(parts[1]),k=parts[2];if(!e.kpiItems[i]||!['target','actual'].includes(k))return;e.kpiItems[i][k]=val.slice(0,200);e.kpiItems[i].verified=false;e.kpiValidated=false;invalidateEvaluation(e);audit(e,'Updated demonstration KPI '+(i+1)+' '+k);}
    else if(field==='kpiSource'){if(!isHR())return;e.kpiSource=val.slice(0,400);e.kpiValidated=false;invalidateEvaluation(e);audit(e,'Updated KPI source note');}
    else if(field.indexOf('score.')===0){const k=field.split('.')[1];if(!canScore(e,k))return;const n=Number(val);if(val===''||!Number.isFinite(n)||n<0||n>100){toast('Scores must be between 0 and 100.');render();return;}e.scores[k]=Math.round(n*100)/100;invalidateEvaluation(e);audit(e,'Updated '+k+' evaluation score');}
    else if(field.indexOf('kitnote.')===0){if(!canTrack(e))return;e.kitNotes[field.slice(8)]=val.slice(0,200);audit(e,'Updated kit issuance or access note');}
    else if(field.indexOf('comment.')===0){const k=field.slice(8);const allowed=k==='hr'?isHR():k==='division'?roleCanHead(e):k==='employee'?isHR():canReview(k);if(!allowed)return;e.comments[k]=val.slice(0,1000);audit(e,'Updated '+k+' comment');}
    else if(['currentBasic','currentAllowances','proposedPct','approvedPct','effectiveDate'].includes(field)){if(field==='approvedPct'||field==='effectiveDate'){return;}else if(!roleCanHead(e))return;
      if(field==='effectiveDate'){if(val&&!/^\d{4}-\d{2}-\d{2}$/.test(val)){toast('Invalid date');return;}e[field]=val;}
      else {const n=Number(val);if(val===''||!Number.isFinite(n)||n<0||(field.endsWith('Pct')&&n>100)){toast('Enter a valid, nonnegative amount (percentages up to 100).');render();return;}e[field]=Math.round(n*100)/100;}
      invalidateEvaluation(e);
      audit(e,'Updated sample compensation: '+field);
    }else return;render();
  }
  function openRecordEditor(id){if(!isHR()){toast('Select a People & Culture (HR) demo role to edit attendance.');return;}const e=emp();let old=id?e.attendance.find(function(x){return x.id===id;}):null;
    const entry={id:old?old.id:'a-'+Date.now(),date:old?old.date:now(),type:old?old.type:'Late',approval:old?old.approval:'Pending',reason:old?old.reason:'',remarks:old?old.remarks:'',verified:old?old.verified:false};
    const modal=document.createElement('div');modal.className='overlay';modal.id='record-modal';modal.innerHTML='<div class="drawer" style="max-width:480px"><div class="drawer-top"><h2>'+(old?'Edit':'Add')+' attendance entry</h2><button class="drawer-close" data-record-close="1" aria-label="Close">×</button></div><p class="muted micro" style="margin-bottom:20px">'+safe(e.name)+' · Verified entries appear in rankings</p><form id="record-form" class="stack"><label><span class="field-label">Date</span><input class="field" name="date" type="date" required value="'+safe(entry.date)+'"></label><label><span class="field-label">Attendance type</span><select class="field" name="type">'+opts(['Late','Absent','Leave'].map(function(x){return {label:x,value:x};}),entry.type)+'</select></label><label><span class="field-label">Approval / excuse status</span><select class="field" name="approval">'+opts(['Pending','Approved','Excused','Unapproved'].map(function(x){return {label:x,value:x};}),entry.approval)+'</select></label><label><span class="field-label">Reason for leave / absence / late arrival</span><textarea class="field textarea" required name="reason">'+safe(entry.reason)+'</textarea></label><label><span class="field-label">Supervisor remarks</span><textarea class="field textarea" name="remarks">'+safe(entry.remarks)+'</textarea></label><label class="check-row"><input type="checkbox" name="verified" '+(entry.verified?'checked':'')+'><span>Verified by HR (counts in analytics)</span></label><button class="button primary" type="submit">Save attendance entry</button></form></div>';document.body.appendChild(modal);
    modal.querySelector('[data-record-close]').addEventListener('click',function(){modal.remove();});
    modal.addEventListener('click',function(ev){if(ev.target===modal)modal.remove();});
    modal.querySelector('#record-form').addEventListener('submit',function(ev){ev.preventDefault();const f=new FormData(ev.currentTarget);const newEntry={id:entry.id,date:String(f.get('date')||''),type:String(f.get('type')||''),approval:String(f.get('approval')||''),reason:String(f.get('reason')||'').trim().slice(0,500),remarks:String(f.get('remarks')||'').trim().slice(0,500),verified:f.has('verified')};if(!newEntry.date||!newEntry.reason){toast('Date and reason are required.');return;}if(old)Object.assign(old,newEntry);else e.attendance.push(newEntry);audit(e,(old?'Edited':'Added')+' attendance record '+newEntry.date);modal.remove();render();toast('Attendance record saved locally.');});
  }
  function reviewAction(step,decision){const e=emp();if(!reviewCanAct(e,step)){toast('This review step is not available to the selected evaluator.');return;}
    if(step==='coo'&&decision==='Approved'&&(!e.effectiveDate||!e.comments.coo.trim())){toast('COO: enter the effectivity date and final remarks before approval.');return;}
    if(step==='division'&&decision==='Endorsed'&&!e.comments.division.trim()){toast('Division Head: add a recommendation comment before endorsement.');return;}
    if(step==='division'){e.review.corp={status:'Pending',comment:'',at:''};e.review.cso={status:'Pending',comment:'',at:''};e.review.coo={status:'Pending',comment:'',at:''};}
    if(decision==='Returned'){const prior=step==='corp'?'division':step==='cso'?'corp':'cso';e.review[prior].status='Pending';}
    e.review[step]={status:decision,comment:e.comments[step]||'',at:new Date().toISOString()};
    if(step==='coo'&&decision==='Approved'&&e.approvedPct===0)toast('Approved with a 0% salary adjustment.');
    audit(e,step+' review: '+decision);render();toast('Review status updated: '+decision+'.');
  }
  function toCSV(rows){return rows.map(function(row){return row.map(function(x){return '"'+String(x===null||x===undefined?'':x).replace(/"/g,'""')+'"';}).join(',');}).join('\r\n');}
  function download(filename,mime,text){const blob=new Blob([text],{type:mime});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(function(){URL.revokeObjectURL(url);},2500);}
  function action(name,button){const e=emp();if(name==='mobile'){ui.mobile=!ui.mobile;render();return;}
    if(name==='nav'){navigate(button.dataset.tab);return;}
    if(name==='goto-division'){openDivision(button.dataset.division);return;}
    if(name==='open'){ui.employee=button.dataset.id||ui.employee;ui.detail=button.dataset.detail||'journey';ui.drawer=true;render();return;}
    if(name==='close'){ui.drawer=false;render();return;}
    if(name==='detail'){ui.detail=button.dataset.tab;render();return;}
    if(name==='new-record'){openRecordEditor();return;}
    if(name==='edit-record'){openRecordEditor(button.dataset.id);return;}
    if(name==='review'){reviewAction(button.dataset.step,button.dataset.decision);return;}
    if(name==='export'){download('maddie-journey-demo-backup.json','application/json;charset=utf-8',JSON.stringify(data,null,2));toast('Backup downloaded.');return;}
    if(name==='export-csv'){const rows=[['Employee ID','Name','Division','Role','Start date','Journey %','Welcome kit %','KPI score %','Performance rating','Final approval']].concat(data.employees.map(function(x){return [x.id,x.name,div(x.division).name,x.jobTitle,x.startDate,journeyPct(x),kitPct(x),score(x),rating(score(x)),x.review.coo.status];}));download('maddie-journey-51-employees.csv','text/csv;charset=utf-8',toCSV(rows));return;}
    if(name==='attendance-csv'){const rows=[['Employee ID','Employee','Division','Date','Type','Approval','Verified','Reason','Supervisor remarks']];data.employees.forEach(function(x){x.attendance.forEach(function(r){rows.push([x.id,x.name,div(x.division).name,r.date,r.type,r.approval,r.verified?'Yes':'No',r.reason,r.remarks]);});});download('maddie-journey-attendance.csv','text/csv;charset=utf-8',toCSV(rows));return;}
    if(name==='import'){$('import-file').click();return;}
    if(name==='reset'){if(confirm('Restore all 51 fictional employees and erase locally saved changes on this browser?')){data=clone(seed);ui.employee=data.employees[0].id;persist();render();toast('Sample data restored.');}return;}
  }
  document.addEventListener('click',function(ev){const dept=ev.target.closest('[data-nav-division]');if(dept){ev.preventDefault();openDivision(dept.dataset.navDivision);return;}const nav=ev.target.closest('[data-nav]');if(nav){ev.preventDefault();navigate(nav.dataset.nav);return;}const act=ev.target.closest('[data-action]');if(act){ev.preventDefault();action(act.dataset.action,act);return;}if(ev.target.dataset.overlay==='true'){ui.drawer=false;render();}});
  document.addEventListener('change',function(ev){const el=ev.target;if(el.dataset.ui){if(el.dataset.ui==='viewer'){ui.viewer=el.value;persist();render();toast('Preview role: '+viewer().name);}else if(el.dataset.ui==='employee'){ui.employee=el.value;render();}else if(el.dataset.ui==='division'){ui.division=el.value;render();}else if(el.dataset.ui==='activeDivision'){openDivision(el.value);}else if(el.dataset.ui==='frequency'){ui.frequency=el.value;render();}else if(el.dataset.ui==='query'){ui.query=el.value;render();}return;}
    if(el.dataset.stage!==undefined){const e=emp();if(!canTrack(e))return;const s=Number(el.dataset.stage),i=Number(el.dataset.item);if(!e.journey[s]||i>=e.journey[s].length)return;e.journey[s][i]=el.checked;audit(e,(el.checked?'Completed':'Reopened')+' Stage '+(s+1)+': '+data.stages[s].items[i]);render();return;}
    if(el.dataset.kit!==undefined){const e=emp(),i=Number(el.dataset.kit);if(!canTrack(e)||i>=e.kit.length)return;e.kit[i]=el.checked;audit(e,(el.checked?'Completed':'Reopened')+' kit: '+data.kit[i].label);render();return;}
    if(el.dataset.field){changeField(el);return;}
    if(el.id==='import-file'&&el.files&&el.files[0]){const r=new FileReader();r.onload=function(){try{const value=JSON.parse(r.result);if(value.version!==seed.version||!Array.isArray(value.employees)||value.employees.length!==51||!Array.isArray(value.divisions)){throw Error('This is not a compatible 51-employee backup.');}if(!confirm('Replace current browser data with this imported backup?'))return;data=value;data.viewers=clone(seed.viewers);data.divisions=clone(seed.divisions);data.stages=clone(seed.stages);data.kit=clone(seed.kit);ui.employee=data.employees[0].id;persist();render();toast('Backup imported successfully.');}catch(err){toast('Import failed: '+err.message);}};r.readAsText(el.files[0]);}
  });
  document.addEventListener('input',function(ev){const el=ev.target;if(el.dataset.ui==='query'){const p=el.selectionStart;ui.query=el.value;const focus=document.activeElement;const list=filtered();const table=$('app').querySelector('.panel.no-pad');if(table){const existing=table.querySelector('.table-wrap, .empty');if(existing)existing.outerHTML=employeesTable(list);const count=table.querySelector('.filters .muted.micro');if(count)count.textContent=list.length+' employees';}if(focus!==el){el.focus();try{el.setSelectionRange(p,p);}catch(err){}}}});
  document.addEventListener('keydown',function(ev){if(ev.key==='Escape'&&ui.drawer){ui.drawer=false;render();}});
  window.addEventListener('hashchange',function(){const target=location.hash.slice(1);if(target.startsWith('division/')){const id=target.slice(9);if(data.divisions.some(function(d){return d.id===id;})&&(ui.tab!=='division'||ui.activeDivision!==id))openDivision(id);}else if(items.some(function(a){return a[0]===target;})&&target!==ui.tab)navigate(target);});
  const hash=location.hash.slice(1);if(hash.startsWith('division/')&&data.divisions.some(function(d){return d.id===hash.slice(9);})) {ui.tab='division';ui.activeDivision=hash.slice(9);}else if(items.some(function(a){return a[0]===hash;}))ui.tab=hash;
  render();
})();